import styled from '@emotion/styled';

import { theme } from '../../../theme';
import type { AvatarSize } from './Avatar.types';

interface StyledAvatarContainerProps {
  $size: AvatarSize;
  $disabled: boolean;
  $backgroundColor: string;
  $backgroundImage?: string;
  $initialsColor: string;
}

interface StyledAvatarOverlayProps {
  $disabled: boolean;
  $variantType: 'initials' | 'image';
}

export const StyledAvatarContainer = styled('div')<StyledAvatarContainerProps>(
  ({
    $size,
    $disabled,
    $backgroundColor,
    $backgroundImage,
    $initialsColor,
  }) => ({
    alignItems: 'center',
    backgroundColor: $backgroundColor,
    backgroundImage: $backgroundImage,
    backgroundPosition: 'center',
    backgroundRepeat: 'no-repeat',
    backgroundSize: 'cover',
    borderRadius: '50%',
    color: $initialsColor,
    cursor: 'default',
    display: 'flex',
    fontFamily: theme.fonts.heading,
    fontSize:
      theme.fonts.fontSizes[
        $size === 'large'
          ? '1'
          : $size === 'xlarge'
            ? '3'
            : $size === 'xxlarge'
              ? '6'
              : '7'
      ],
    fontWeight: theme.fonts.fontWeights.semibold,
    height: {
      large: '24px',
      xlarge: '32px',
      xxlarge: '64px',
      xxxlarge: '96px',
    }[$size],
    justifyContent: 'center',
    opacity: $disabled ? 0.4 : 1,
    width: {
      large: '24px',
      xlarge: '32px',
      xxlarge: '64px',
      xxxlarge: '96px',
    }[$size],
  }),
);

export const StyledAvatarOverlay = styled('div')<StyledAvatarOverlayProps>(
  ({ $disabled, $variantType }) => ({
    alignItems: 'center',
    border:
      $disabled && $variantType === 'initials'
        ? `2px solid ${theme.colors.interfaceSurfaceSecondary}`
        : 'none',
    borderRadius: '50%',
    cursor: 'default',
    display: 'flex',
    height: '100%',
    justifyContent: 'center',
    textAlign: 'center',
    transition: 'background 0.2s ease-in-out',
    width: '100%',
    ...($disabled
      ? {
          background: 'none',
          '&:hover': {
            background: 'none',
          },
        }
      : {
          '&:hover': {
            background: theme.colors.interfaceSurfaceSecondary,
          },
        }),
  }),
);
